function SEO({ title, description, image = '/media/afaqyomi_logo.png' }: { title: string; description: string; image?: string }) {
  useEffect(() => {
    document.title = title;
    const setMeta = (name: string, content: string, property = false) => {
      const selector = property ? `meta[property="${name}"]` : `meta[name="${name}"]`;
      let node = document.head.querySelector(selector) as HTMLMetaElement | null;
      if (!node) { node = document.createElement('meta'); if (property) node.setAttribute('property', name); else node.setAttribute('name', name); document.head.appendChild(node); }
      node.content = content;
    };
    setMeta('description', description);
    setMeta('og:title', title, true);
    setMeta('og:description', description, true);
    setMeta('og:image', `${window.location.origin}${image}`, true);
    setMeta('twitter:card', 'summary_large_image');
    setMeta('twitter:title', title);
    setMeta('twitter:description', description);
  }, [description, image, title]);
  return null;
}

